"use strict";(self.webpackChunkcurvine_doc=self.webpackChunkcurvine_doc||[]).push([[2110],{23013:(e,t,n)=>{n.d(t,{A:()=>r});const r=n.p+"assets/images/figure-5-63952b2dcacff4e24ef26e04c6b57ad0.png"},28453:(e,t,n)=>{n.d(t,{R:()=>o,x:()=>i});var r=n(96540);const a={},s=r.createContext(a);function o(e){const t=r.useContext(s);return r.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:o(e.components),r.createElement(s.Provider,{value:t},e.children)}},38346:(e,t,n)=>{n.d(t,{A:()=>r});const r=n.p+"assets/images/figure-2-cfb5491bc68d89ea8a0efa2b7f7734fe.png"},51965:e=>{e.exports=JSON.parse('{"permalink":"/blog/2026/08/13/tiered-kv-cache-sagemaker-hyperpod-curvine","editUrl":"https://github.com/curvineio/curvine-doc/edit/main/blog/blog/2026-08-13-tiered-kv-cache-sagemaker-hyperpod-curvine/index.md","source":"@site/blog/2026-08-13-tiered-kv-cache-sagemaker-hyperpod-curvine/index.md","title":"tiered-kv-cache-sagemaker-hyperpod-curvine","description":"Running large language model (LLM) inference at scale typically forces a KV cache trade-off: you either pay for oversized GPU instances to accommodate a growing KV cache, or you accept slow time-to-first-token (TTFT) as identical prompts get recomputed on every request. For teams deploying a broad catalog of publicly available foundation models (FMs), such as Qwen, Llama, DeepSeek, and others, across per-business-line endpoints, Retrieval Augmented Generation (RAG) pipelines, or multi-turn dialogue applications, this trade-off translates directly into higher infrastructure cost and degraded user experience.","date":"2026-08-13T00:00:00.000Z","tags":[{"inline":false,"label":"Hello","permalink":"/blog/tags/ai","description":"curvine in ai"},{"inline":false,"label":"benchmark","permalink":"/blog/tags/benchmark","description":"benchmark of curvine"}],"readingTime":31.28,"hasTruncateMarker":true,"authors":[{"name":"David","title":"Founder of Curvine","url":"https://curvine.io","page":{"permalink":"/blog/authors/all-sebastien-lorber-articles"},"socials":{"github":"https://github.com/szbr9486","x":"https://x.com/szbr8896"},"key":"david"}],"frontMatter":{"authors":["david"],"tags":["ai","benchmark"]},"unlisted":false,"nextItem":{"title":"curvine-ltp-compatibility","permalink":"/blog/2026/08/11/curvine-ltp-compatibility"}}')},57706:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>c,contentTitle:()=>i,default:()=>h,frontMatter:()=>o,metadata:()=>r,toc:()=>l});var r=n(51965),a=n(74848),s=n(28453);const o={authors:["david"],tags:["ai","benchmark"]},i="Tiered KV cache for large LLMs on Amazon SageMaker HyperPod with Curvine",c={authorsImageUrls:[void 0]},l=[{value:"Solution design",id:"solution-design",level:2},{value:"Prerequisites",id:"prerequisites",level:2},{value:"Step-by-step implementation",id:"step-by-step-implementation",level:2},{value:"Stage 1: Enable HyperPod Tiered Storage",id:"stage-1-enable-hyperpod-tiered-storage",level:3},{value:"Stage 2: Install the Inference Operator and dependencies",id:"stage-2-install-the-inference-operator-and-dependencies",level:3},{value:"Stage 3: Deploy the Curvine distributed cache",id:"stage-3-deploy-the-curvine-distributed-cache",level:3},{value:"Install the Curvine CSI",id:"install-the-curvine-csi",level:4},{value:"Install the Curvine server (Primary + Worker components)",id:"install-the-curvine-server-primary--worker-components",level:4},{value:"Create a ReadWriteMany (RWX) PVC for inference Pods",id:"create-a-readwritemany-rwx-pvc-for-inference-pods",level:4},{value:"Stage 4: Deploy a vLLM endpoint with tiered KV cache",id:"stage-4-deploy-a-vllm-endpoint-with-tiered-kv-cache",level:3},{value:"Deploy using the Inference Operator",id:"deploy-using-the-inference-operator",level:4},{value:"Patch the Deployment to mount the Curvine PVC",id:"patch-the-deployment-to-mount-the-curvine-pvc",level:4},{value:"Stage 5: Verify L2 write, hit, and cross-Pod sharing",id:"stage-5-verify-l2-write-hit-and-cross-pod-sharing",level:3},{value:"Benchmarking",id:"benchmarking",level:2},{value:"Solution benefits",id:"solution-benefits",level:2},{value:"Enabling KV cache for large models on small instances: NVMe as a safety net",id:"enabling-kv-cache-for-large-models-on-small-instances-nvme-as-a-safety-net",level:3},{value:"Unified FUSE mount for cross-Pod L2 cache sharing",id:"unified-fuse-mount-for-cross-pod-l2-cache-sharing",level:3},{value:"Operations and cost",id:"operations-and-cost",level:3},{value:"Clean up",id:"clean-up",level:2},{value:"Conclusion",id:"conclusion",level:2}];function d(e){const t={a:"a",code:"code",em:"em",h2:"h2",h3:"h3",h4:"h4",hr:"hr",img:"img",li:"li",p:"p",pre:"pre",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,s.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.p,{children:"Running large language model (LLM) inference at scale typically forces a KV cache trade-off: you either pay for oversized GPU instances to accommodate a growing KV cache, or you accept slow time-to-first-token (TTFT) as identical prompts get recomputed on every request. For teams deploying a broad catalog of publicly available foundation models (FMs), such as Qwen, Llama, DeepSeek, and others, across per-business-line endpoints, Retrieval Augmented Generation (RAG) pipelines, or multi-turn dialogue applications, this trade-off translates directly into higher infrastructure cost and degraded user experience."}),"\n",(0,a.jsx)(t.p,{children:"The root cause is straightforward. During generation, vLLM stores the attention keys and values for every token it has already processed in a KV cache, so it doesn't recompute them on each step. Prefix caching extends this by reusing that cache across requests that share the same leading tokens (like a common system prompt). On cost-efficient instances like ml.g6e.4xlarge (48 GB per GPU), once model weights and runtime allocations are accounted for, the memory left for prefix caching is limited, and it tightens further with larger models or higher concurrency. Cache hit rates drop on long prompts, identical system prompts get re-prefilled on every request, and horizontally scaled vLLM replicas each maintain isolated caches. Routing to a different replica is functionally a cold start."}),"\n",(0,a.jsx)(t.p,{children:"In this post, we build a tiered KV cache architecture on Amazon SageMaker HyperPod that extends the cache hierarchy beyond GPU and CPU memory into a shared, distributed NVMe pool. It builds on two HyperPod capabilities, Managed Tiered KV Cache and Intelligent Routing, and adds Curvine, a lightweight distributed cache filesystem, as the shared L2 tier (GPU to CPU to shared NVMe). With this setup, you can reuse KV cache across replicas at near-local-disk speeds."}),"\n",(0,a.jsx)(t.p,{children:"We walk through the end-to-end implementation, from enabling HyperPod Tiered Storage to deploying Curvine workers on node-local NVMe to patching the Inference Operator for filesystem-backed L2. On a test deployment, this achieved up to a 100 percent cross-Pod cache hit rate, up to a 2.7x TTFT improvement, and cross-node L2 read latency of about 56 ms for a approximately 1,900-token prompt. See the Benchmarking section for the full methodology and results. With this architecture, workloads that previously required P5 instances can run on lower-cost G6e instances, reducing per-endpoint cost. Actual savings depend on model size and traffic profile."}),"\n",(0,a.jsx)(t.h2,{id:"solution-design",children:"Solution design"}),"\n",(0,a.jsx)(t.p,{children:"The central idea is to extend the KV cache beyond what fits on a single Pod. Rather than accepting that each vLLM replica lives in isolation, which is its own GPU blocks, its own CPU spill area, no sharing, we build a three-tier hierarchy: L0 (GPU HBM), L1 (local CPU/host memory), and L2 (Curvine, a shared cross-node cache), and overlay it with cache-aware request routing."}),"\n",(0,a.jsx)(t.p,{children:"L0 \u2013 GPU prefix cache. This is vLLM's native paged-attention layer, holding the hottest KV blocks at the lowest access latency, but its capacity is only whatever GPU memory is left after the model weights. On a 48 GB GPU, a 7B model in bf16 uses around 14 GB for weights, leaving over 30 GB for KV blocks, which is plenty of headroom, so L0 pressure is minimal. A 32B model uses around 64 GB of weights and doesn't even fit on one 48 GB GPU. Even after sharding, far less memory remains for KV, so the cache fills quickly and evicts under concurrency. That shrinking headroom is exactly why extending the cache off-GPU matters as you scale up model size and traffic."}),"\n",(0,a.jsxs)(t.p,{children:["L1 \u2013 CPU memory offload. When GPU blocks are evicted, LMCache catches them in host DRAM before they're lost. This runs inside each inference Pod and is managed automatically by the SageMaker HyperPod Inference Operator when you set",(0,a.jsx)(t.code,{children:"enableL1Cache: true"})," in the InferenceEndpointConfig CRD. Think of it as a safety net. It's fast, Pod-local, and sized by InstanceMemoryAllocationPercentage (we recommend starting at 20 percent)."]}),"\n",(0,a.jsx)(t.p,{children:"L2 \u2013 Shared distributed NVMe pool. This is where cross-replica reuse happens. Curvine, a lightweight distributed cache filesystem, pools the local NVMe drives that ship with G6e/P5 instances into a single namespace, which a FUSE client (a user-space driver that presents the pool as an ordinary mounted directory) mounts as a ReadWriteMany PVC (PersistentVolumeClaim) into every inference Pod. LMCache reads and writes through its fs:// connector, so the distributed pool looks like a local directory. Because every Pod mounts the same namespace, a KV block written by one replica is immediately readable by others."}),"\n",(0,a.jsx)(t.p,{children:"Curvine itself is straightforward to operate: a Primary Node (called the \"Master\" in Curvine's documentation) handles metadata and journaling, persisted on Amazon Elastic Block Store (Amazon EBS) for durability, while Worker components run on each GPU node and store data on the node's NVMe (typically mounted at /opt/dlami/nvme/curvine-data). If a Worker dies, the cache it held is recomputed, no data-loss concern, since these are reproducible KV blocks."}),"\n",(0,a.jsx)(t.p,{children:"Intelligent routing \u2013 getting requests to the right replica. A three-tier cache only delivers its full benefit if requests land on replicas that already hold relevant KV blocks. The HyperPod Inference Operator includes a built-in router that supports three strategies:"}),"\n",(0,a.jsxs)(t.table,{children:[(0,a.jsx)(t.thead,{children:(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.th,{children:"Strategy"}),(0,a.jsx)(t.th,{children:"Best for"})]})}),(0,a.jsxs)(t.tbody,{children:[(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"prefix-aware (default)"}),(0,a.jsx)(t.td,{children:"Multi-turn dialogue, shared system prompts"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"kv-aware"}),(0,a.jsx)(t.td,{children:"Long document processing, extended sessions"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"round-robin"}),(0,a.jsx)(t.td,{children:"Stateless batch inference, load testing"})]})]})]}),"\n",(0,a.jsx)(t.p,{children:"The router maintains a prefix tree (prefix-aware) or queries each worker's cache state (kv-aware) to select the replica most likely to produce a cache hit. This happens transparently, no client-side changes are needed."}),"\n",(0,a.jsxs)(t.p,{children:["How these pieces fit together. The Inference Operator is installed as an Amazon Elastic Kubernetes Service (Amazon EKS) add-on and manages the full lifecycle. It spins up vLLM Pods with LMCache sidecars, configures L1 and L2 backends, deploys the router, and exposes a single load-balanced endpoint. You declare the cache topology you want in the InferenceEndpointConfig CRD (",(0,a.jsx)(t.code,{children:"enableL1Cache"}),",",(0,a.jsx)(t.code,{children:"enableL2Cache"}),",",(0,a.jsx)(t.code,{children:"l2CacheBackend"}),",",(0,a.jsx)(t.code,{children:"routingStrategy"}),"), and the Operator renders the correct environment variables, volume mounts, and routing rules. The one caveat today: the CRD's",(0,a.jsx)(t.code,{children:"l2CacheBackend"})," field only accepts",(0,a.jsx)(t.code,{children:"redis"})," or",(0,a.jsx)(t.code,{children:"tieredstorage"})," natively. To point L2 at a Curvine FUSE mount, we patch the",(0,a.jsx)(t.code,{children:"LMCACHE_REMOTE_URL"})," environment variable in the vLLM container spec to",(0,a.jsx)(t.code,{children:"fs://localhost:0/mnt/curvine/l2cache/"}),". We walk through this patch in Stage 4 of the implementation."]}),"\n",(0,a.jsx)(t.p,{children:"The net effect is a request arrives at the router, gets dispatched to the replica with the best prefix match, that replica checks GPU blocks (L0), then CPU (L1), then the shared NVMe pool (L2). Only on a complete miss does it re-prefill from scratch. For workloads with moderate-to-high prompt overlap (roughly over 40 percent shared leading tokens, for example a common system prompt or shared RAG context), skipping that re-prefill substantially reduces TTFT."}),"\n",(0,a.jsx)(t.p,{children:"Figure 1 shows the full data path. Each vLLM Pod stacks an L0 GPU prefix cache and an L1 CPU offload. Below them, all Pods share the L2 tier on a Curvine distributed filesystem pooled from node-local NVMe and mounted ReadWriteMany over FUSE, while the Curvine metadata node persists to Amazon EBS. The HyperPod Intelligent Router sits in front, directing each request to the replica most likely to already hold the relevant cache."}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"Figure 1: Tiered KV cache architecture",src:n(87329).A+"",width:"1882",height:"1423"})}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.em,{children:"Figure 1: Tiered KV cache architecture"})}),"\n",(0,a.jsx)(t.p,{children:"Curvine is a high-performance distributed cache file system that sits between applications and underlying storage such as Amazon Simple Storage Service (Amazon S3), HDFS, or NAS. Clients reach it through the CLI, SDK, FUSE, or CSI. Primary Nodes handle metadata, and Workers serve data with local disk cache for low-latency I/O. Figure 2 shows the Curvine architecture and its key components."}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"Figure 2: Curvine architecture",src:n(38346).A+"",width:"1804",height:"1428"})}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.em,{children:"Figure 2: Curvine architecture"})}),"\n",(0,a.jsx)(t.p,{children:"How Curvine works (cluster view):"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsx)(t.li,{children:"Clients send metadata RPC to Masters and data I/O to Workers."}),"\n",(0,a.jsx)(t.li,{children:"Masters coordinate Workers using heartbeats and place blocks for load balance and HA."}),"\n",(0,a.jsx)(t.li,{children:"Workers read/write local tiers and promote/demote data by heat."}),"\n",(0,a.jsx)(t.li,{children:"On miss or policy-driven persistence, Curvine loads from / dumps to UFS, so durability stays on the underlying store while Curvine accelerates access."}),"\n"]}),"\n",(0,a.jsx)(t.h2,{id:"prerequisites",children:"Prerequisites"}),"\n",(0,a.jsxs)(t.p,{children:["Amazon SageMaker HyperPod Tiered Storage is a cluster-level capability that provisions a node-local cache tier for inference workloads. After Tiered Storage is active, SageMaker HyperPod deploys the ai-toolkit DaemonSet on every GPU node, reserves a configurable share of host memory (InstanceMemoryAllocationPercentage) for the L1 CPU offload, and exposes the local NVMe instance store under /opt/dlami/nvme so that Curvine Workers can pool it into a shared L2 namespace. The Inference Operator consumes these tiers automatically when",(0,a.jsx)(t.code,{children:"enableL1Cache"})," and",(0,a.jsx)(t.code,{children:"enableL2Cache"})," are set on the InferenceEndpointConfig CRD."]}),"\n",(0,a.jsx)(t.p,{children:"This walkthrough assumes a SageMaker HyperPod cluster orchestrated by Amazon EKS. To create one, follow Orchestrating SageMaker HyperPod clusters with Amazon EKS in the SageMaker documentation, or with AWS CloudFormation, using the reference templates on the AWSome Distributed AI repository. Provision at least two GPU nodes. A single node can't demonstrate cross-node reuse. Throughout this post we use the cluster name hyperpod-cluster-eks and the US West (Oregon) AWS Region (us-west-2) as examples, replace them with your own cluster name and Region to reproduce this solution in your account."}),"\n",(0,a.jsx)(t.p,{children:"Verify the following are in place:"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsx)(t.li,{children:"GPU capacity with local NVMe: A SageMaker HyperPod EKS cluster with at least one GPU instance group. G6e or P5 is recommended for their local NVMe, which Curvine pools into L2."}),"\n",(0,a.jsxs)(t.li,{children:["CLI tooling: On your workstation: AWS Command Line Interface (AWS CLI) v2 (with permissions for",(0,a.jsx)(t.code,{children:"sagemaker:UpdateCluster"})," and",(0,a.jsx)(t.code,{children:"eks:CreateAddon)"}),", kubectl configured against the cluster with",(0,a.jsx)(t.code,{children:"aws eks update-kubeconfig"}),", and Helm v3."]}),"\n",(0,a.jsxs)(t.li,{children:["AWS Identity and Access Management (IAM) for EBS attach: Grant the EBS CSI driver role",(0,a.jsx)(t.code,{children:"sagemaker:AttachClusterNodeVolume"}),",",(0,a.jsx)(t.code,{children:"sagemaker:DetachClusterNodeVolume"}),", and",(0,a.jsx)(t.code,{children:"eks:Describe*"})," so the Curvine metadata node can attach its EBS volume. Keep the Amazon Virtual Private Cloud (Amazon VPC) CNI and EBS CSI add-ons current."]}),"\n",(0,a.jsx)(t.li,{children:"Model weights: this post pulls Qwen2-7B from HuggingFace, so no bucket is required. To stage weights yourself, use an Amazon S3 bucket with the SageMaker HyperPod execution role granted read access. TLS certificates are generated automatically."}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"Tiered Storage is enabled in Stage 1. The Inference Operator, Amazon S3 and Amazon FSx CSI drivers, Metrics Server, and Cert Manager are installed in Stage 2 (or through console Quick Install), the EBS CSI driver and Curvine in Stage 3."}),"\n",(0,a.jsx)(t.h2,{id:"step-by-step-implementation",children:"Step-by-step implementation"}),"\n",(0,a.jsx)(t.p,{children:"The following procedure uses this implementation as a worked example, organized into five stages. Cluster names and Regions shown are placeholders, substitute your own."}),"\n",(0,a.jsx)(t.h3,{id:"stage-1-enable-hyperpod-tiered-storage",children:"Stage 1: Enable HyperPod Tiered Storage"}),"\n",(0,a.jsx)(t.p,{children:"Tiered Storage is a cluster-level toggle. Once Tiered Storage is active, HyperPod automatically deploys the ai-toolkit DaemonSet to every node."}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:"# Enable on an existing cluster via update-cluster (recommended)\naws sagemaker update-cluster \\\n  --cluster-name hyperpod-cluster-eks \\\n  --tiered-storage-config Mode=Enable,InstanceMemoryAllocationPercentage=20 \\\n  --node-recovery Automatic\n"})}),"\n",(0,a.jsxs)(t.p,{children:["API note. Calling",(0,a.jsx)(t.code,{children:"update-cluster"})," with",(0,a.jsx)(t.code,{children:"--tiered-storage-config"})," alone returns",(0,a.jsx)(t.code,{children:"ValidationException"}),". At least one of",(0,a.jsx)(t.code,{children:"--node-recovery"})," or",(0,a.jsx)(t.code,{children:"--instance-groups"})," must also be supplied. The approach is to read the current",(0,a.jsx)(t.code,{children:"NodeRecovery"})," value by running",(0,a.jsx)(t.code,{children:"describe-cluster"})," and pass it back unchanged. This has no side effect on the cluster configuration."]}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.code,{children:"InstanceMemoryAllocationPercentage"})," accepts 20\u2013100. Begin at 20 and increase as needed based on observed throughput and hit rate. Verify with the following commands:"]}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:'aws sagemaker describe-cluster --cluster-name hyperpod-cluster-eks \\\n  --query \'TieredStorageConfig\'\n# Expected: {"Mode": "Enable", "InstanceMemoryAllocationPercentage": 20}\n\nkubectl get ds -n aws-hyperpod ai-toolkit\n# Expected:\n# NAME        DESIRED  CURRENT  READY  UP-TO-DATE  AVAILABLE  NODE SELECTOR  AGE\n# ai-toolkit  2        2        2      2           2          <none>         45s\n'})}),"\n",(0,a.jsx)(t.h3,{id:"stage-2-install-the-inference-operator-and-dependencies",children:"Stage 2: Install the Inference Operator and dependencies"}),"\n",(0,a.jsx)(t.p,{children:"The most convenient approach is Quick Install in the SageMaker console, which provisions the IAM role and installs S3 CSI, FSx CSI, Metrics Server, Cert Manager, and the Inference Operator in one action. The CLI alternative:"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:"EKS_CLUSTER_NAME=$(aws sagemaker describe-cluster --cluster-name hyperpod-cluster-eks \\\n  --query 'Orchestrator.Eks.ClusterArn' --output text | cut -d'/' -f2)\n\nfor addon in aws-mountpoint-s3-csi-driver aws-fsx-csi-driver metrics-server cert-manager; do\n  aws eks create-addon --cluster-name $EKS_CLUSTER_NAME --addon-name $addon --region us-west-2\ndone\n\naws eks create-addon \\\n  --cluster-name $EKS_CLUSTER_NAME \\\n  --addon-name amazon-sagemaker-hyperpod-inference \\\n  --configuration-values file://addon-config.json \\\n  --region us-west-2\n"})}),"\n",(0,a.jsx)(t.h3,{id:"stage-3-deploy-the-curvine-distributed-cache",children:"Stage 3: Deploy the Curvine distributed cache"}),"\n",(0,a.jsxs)(t.p,{children:["Several prerequisites must be in place before deploying Curvine. Upgrade the VPC CNI plugin and the EBS CSI driver to a current version, with IRSA preferred over Pod Identity to avoid additional IP consumption on nodes. Grant the",(0,a.jsx)(t.code,{children:"aws-ebs-csi-dri-role"})," the EBS-attach permissions listed in Prerequisites (without them, EBS attach on SageMaker HyperPod nodes returns",(0,a.jsx)(t.code,{children:"ValidationException"}),"). Finally, verify an EBS StorageClass (for example",(0,a.jsx)(t.code,{children:"ebs-sc"}),") is available in the cluster. Check the actual name with",(0,a.jsx)(t.code,{children:"kubectl get sc"}),". On SageMaker HyperPod EKS clusters the default EBS StorageClass is often",(0,a.jsx)(t.code,{children:"gp3"}),". Use that name for",(0,a.jsx)(t.code,{children:"master.storage.meta.storageClass"})," and",(0,a.jsx)(t.code,{children:"master.storage.journal.storageClass"})," in the Helm install that follows, or create an",(0,a.jsx)(t.code,{children:"ebs-sc"})," StorageClass first:"]}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:"apiVersion: storage.k8s.io/v1\nkind: StorageClass\nmetadata:\n  name: ebs-sc\nprovisioner: ebs.csi.aws.com\nvolumeBindingMode: WaitForFirstConsumer\nreclaimPolicy: Delete\n"})}),"\n",(0,a.jsx)(t.h4,{id:"install-the-curvine-csi",children:"Install the Curvine CSI"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:"helm repo add curvine https://curvineio.github.io/helm-charts\nhelm repo update\n\nhelm install curvine-csi curvine/curvine-csi \\\n  -n curvine --create-namespace \\\n  --version 0.3.2-alpha \\\n  --set controller.sidecars.provisioner.image=registry.k8s.io/sig-storage/csi-provisioner:v3.6.0 \\\n  --set node.sidecars.nodeDriverRegistrar.image=registry.k8s.io/sig-storage/csi-node-driver-registrar:v2.10.0 \\\n  --set controller.container.securityContext.privileged=true \\\n  --set node.container.securityContext.privileged=true\n\nkubectl get csidrivers | grep curvine  # confirm driver registered\n"})}),"\n",(0,a.jsx)(t.p,{children:"The CSI install doesn't create a StorageClass automatically. One must be created manually:"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:'kubectl apply -f - <<\'EOF\'\napiVersion: storage.k8s.io/v1\nkind: StorageClass\nmetadata:\n  name: curvine-sc\nprovisioner: curvine\nreclaimPolicy: Delete\nvolumeBindingMode: Immediate\nallowVolumeExpansion: true\nparameters:\n  master-addrs: "curvine-master-0.curvine-master.curvine.svc.cluster.local:8995"\n  fs-path: "/l2cache"\n  path-type: "DirectoryOrCreate"\nEOF\n\nkubectl get sc curvine-sc  # confirm curvine-sc created\n'})}),"\n",(0,a.jsxs)(t.p,{children:["Curvine CSI 0.3.x and later requires three StorageClass parameters:",(0,a.jsx)(t.code,{children:"master-addrs"}),"(the Curvine master RPC endpoint, which must match the service DNS created by the Helm install, and comma-separate multiple addresses if the master component has replicas),",(0,a.jsx)(t.code,{children:"fs-path"}),"(the mount-path prefix inside the Curvine filesystem), and",(0,a.jsx)(t.code,{children:"path-type"}),"(",(0,a.jsx)(t.code,{children:"DirectoryOrCreate"})," lets the CSI create the directory automatically). Without them, PVC provisioning fails with",(0,a.jsx)(t.code,{children:"Parameter 'master-addrs' is required"}),"."]}),"\n",(0,a.jsx)(t.h4,{id:"install-the-curvine-server-primary--worker-components",children:"Install the Curvine server (Primary + Worker components)"}),"\n",(0,a.jsx)(t.p,{children:"For KV cache workloads, node-local NVMe with hostPath is the recommended Worker data backend: G6e/P5 instances ship with NVMe (approximately 3 GB/s), which delivers far higher performance than EBS gp3, incurs no additional cost, and is acceptable for caches where loss is recoverable."}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:'# Step 1: first-time install (bootstrap). Format flags initialise the\n# metadata / journal / data directories. Required on 0.3.x, otherwise the\n# master pod fails with "RocksDB directories not found".\nhelm install curvine curvine/curvine -n curvine --create-namespace \\\n  --version 0.3.2-alpha \\\n  --set image.pullPolicy=Always \\\n  --set cluster.formatMaster=true \\\n  --set cluster.formatWorker=true \\\n  --set cluster.formatJournal=true \\\n  --set master.replicas=1 \\\n  --set worker.replicas=2 \\\n  --set "master.nodeSelector.sagemaker\\.amazonaws\\.com/compute-type=hyperpod" \\\n  --set "worker.nodeSelector.sagemaker\\.amazonaws\\.com/compute-type=hyperpod" \\\n  --set master.storage.meta.storageClass=ebs-sc \\\n  --set master.storage.journal.storageClass=ebs-sc \\\n  --set "worker.storage.dataDirs[0].name=data1" \\\n  --set "worker.storage.dataDirs[0].type=SSD" \\\n  --set "worker.storage.dataDirs[0].enabled=true" \\\n  --set "worker.storage.dataDirs[0].size=100Gi" \\\n  --set "worker.storage.dataDirs[0].storageClass=" \\\n  --set "worker.storage.dataDirs[0].hostPath=/opt/dlami/nvme/curvine-data" \\\n  --set "worker.storage.dataDirs[0].mountPath=/data/data1"\n\n# Step 2: once all pods are Running, IMMEDIATELY disable the format flags\n# so a future pod restart cannot re-format and wipe existing cache/metadata:\nhelm upgrade curvine curvine/curvine -n curvine \\\n  --version 0.3.2-alpha --reuse-values \\\n  --set cluster.formatMaster=false \\\n  --set cluster.formatWorker=false \\\n  --set cluster.formatJournal=false\n\nkubectl get pods -n curvine  # confirm pods stay Running / come back cleanly\n'})}),"\n",(0,a.jsxs)(t.p,{children:["Constraints. Master meta and journal must use durable EBS storage. Loss of metadata or WAL upon node rebuild isn't acceptable. When the Worker",(0,a.jsx)(t.code,{children:"dataDirs[0].storageClass"})," is empty and",(0,a.jsx)(t.code,{children:"hostPath"})," is set, the Helm chart enables hostPath mode. The two are mutually exclusive and exactly one must be chosen."]}),"\n",(0,a.jsx)(t.h4,{id:"create-a-readwritemany-rwx-pvc-for-inference-pods",children:"Create a ReadWriteMany (RWX) PVC for inference Pods"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:"kubectl apply -f - <<'EOF'\napiVersion: v1\nkind: PersistentVolumeClaim\nmetadata:\n  name: curvine-pvc\n  namespace: default\nspec:\n  accessModes:\n    - ReadWriteMany\n  storageClassName: curvine-sc\n  resources:\n    requests:\n      storage: 100Gi\nEOF\n\nkubectl get pvc curvine-pvc  # WAIT for Bound before proceeding\n"})}),"\n",(0,a.jsx)(t.h3,{id:"stage-4-deploy-a-vllm-endpoint-with-tiered-kv-cache",children:"Stage 4: Deploy a vLLM endpoint with tiered KV cache"}),"\n",(0,a.jsx)(t.p,{children:"With Tiered Storage enabled, the operator installed, and Curvine running, the final stage deploys the inference endpoint and points its L2 cache at Curvine. This involves three steps: declaring the endpoint with an InferenceEndpointConfig CRD, patching the rendered Deployment to mount the Curvine PVC, and overriding the operator-injected cache URL so L2 reads and writes go to Curvine."}),"\n",(0,a.jsx)(t.h4,{id:"deploy-using-the-inference-operator",children:"Deploy using the Inference Operator"}),"\n",(0,a.jsx)(t.p,{children:"Apply the InferenceEndpointConfig CRD below (deploy-qwen-kvcache.yaml). The SageMaker HyperPod Inference Operator reconciles it into a Deployment, vLLM Pods (each with an LMCache sidecar), the intelligent router, and a single load-balanced endpoint. Three points differ from a stock deployment:"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:["Model source is huggingface: the Operator's built-in init container downloads the weights to",(0,a.jsx)(t.code,{children:"/opt/ml/model"})," at Pod startup, so no S3 staging is needed. (Set",(0,a.jsx)(t.code,{children:"modelSourceType: s3"})," with an s3Storage block if you prefer to stage weights yourself.)"]}),"\n",(0,a.jsx)(t.li,{children:"LMCACHE_REMOTE_URL is intentionally NOT listed in the CRD. When enableL2Cache: true, the Operator injects its own value. Declaring it here as well produces a duplicate env entry that you would then need to find and remove by index. Leave it out and override the injected value with the patch in the next section."}),"\n",(0,a.jsx)(t.li,{children:"tlsConfig is omitted: it's not a required field, and the Operator auto-generates the endpoint certificate into its default output bucket."}),"\n"]}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:'# deploy-qwen-kvcache.yaml\napiVersion: inference.sagemaker.aws.amazon.com/v1\nkind: InferenceEndpointConfig\nmetadata:\n  name: qwen2-7b-instruct-kvcache\n  namespace: default\nspec:\n  modelName: qwen2-7b-instruct\n  instanceType: ml.g6e.4xlarge\n  invocationEndpoint: v1/chat/completions\n  replicas: 2\n  modelSourceConfig:\n    modelSourceType: huggingface   # Operator downloads weights to /opt/ml/model\n    prefetchEnabled: true\n    huggingFaceModel:\n      modelId: Qwen/Qwen2-7B-Instruct   # public model; add tokenSecretRef for gated models\n  kvCacheSpec:\n    enableL1Cache: true\n    enableL2Cache: true\n    l2CacheSpec:\n      l2CacheBackend: "tieredstorage"   # placeholder to pass CRD validation; overridden by the Stage 4 patch\n  intelligentRoutingSpec:\n    enabled: true\n    routingStrategy: prefixaware\n  # tlsConfig is intentionally omitted: the Operator auto-generates the\n  # endpoint certificate into its default output bucket.\n  metrics:\n    enabled: true\n    modelMetrics:\n      port: 8000\n  loadBalancer:\n    healthCheckPath: /health\n  worker:\n    image: public.ecr.aws/deep-learning-containers/vllm:0.11.1-gpu-py312-cu129-ubuntu22.04-ec2-v1.0\n    args:\n      - "--model"\n      - "/opt/ml/model"\n      - "--max-model-len"\n      - "16384"\n      - "--tensor-parallel-size"\n      - "1"\n    resources:\n      limits:\n        nvidia.com/gpu: "1"\n      requests:\n        cpu: "8"\n        memory: 32Gi\n        nvidia.com/gpu: "1"\n    modelInvocationPort:\n      containerPort: 8000\n      name: http\n    modelVolumeMount:\n      name: model-weights\n      mountPath: /opt/ml/model\n    environmentVariables:\n      # Do NOT add LMCACHE_REMOTE_URL here: when enableL2Cache is true the\n      # Operator injects its own value; declaring it here creates a duplicate\n      # env entry. It is replaced with the Curvine fs:// URL by the Stage 4\n      # patch after the Deployment is rendered.\n      - name: LMCACHE_REMOTE_SERDE\n        value: "naive"   # cachegen serde has a zip bug under the fs connector\n      - name: PYTHONHASHSEED\n        value: "0"   # required: identical cache keys across Pods\n'})}),"\n",(0,a.jsx)(t.p,{children:"Two of those environment variables deserve explanation, because both look arbitrary and neither is:"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:["LMCACHE_REMOTE_SERDE=naive \u2013 the",(0,a.jsx)(t.code,{children:"cachegen"})," serializer has a zip-serialization bug under LMCache's filesystem connector. The",(0,a.jsx)(t.code,{children:"naive"})," serializer is the stable choice."]}),"\n",(0,a.jsx)(t.li,{children:"PYTHONHASHSEED=0 \u2013 LMCache derives cache keys from Python hashes. Without a pinned seed, each Pod computes different keys for the same prompt and cross-Pod sharing silently doesn't hit."}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"Apply it and wait for both Pods to become Ready (each Pod runs three containers: vLLM, reverse-proxy, otel-collector):"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:"kubectl apply -f deploy-qwen-kvcache.yaml\nkubectl get pods -l app=qwen2-7b-instruct-kvcache -w   # WAIT: 2 Pods, 3/3 Running\n"})}),"\n",(0,a.jsx)(t.h4,{id:"patch-the-deployment-to-mount-the-curvine-pvc",children:"Patch the Deployment to mount the Curvine PVC"}),"\n",(0,a.jsxs)(t.p,{children:["The Operator-rendered Deployment needs two adjustments that the CRD cannot express: mounting the Curvine PVC into the vLLM container, and repointing L2 at the FUSE mount. When",(0,a.jsx)(t.code,{children:"enableL2Cache: true"}),", the Operator injects",(0,a.jsx)(t.code,{children:"LMCACHE_REMOTE_URL=sagemaker-hyperpod://$(NODE_IP):9200"}),"(its node-local backend), and because",(0,a.jsx)(t.code,{children:"l2CacheBackend"})," accepts only",(0,a.jsx)(t.code,{children:"redis"})," or",(0,a.jsx)(t.code,{children:"tieredstorage"}),", there's no CRD field to point L2 at a Curvine path. So we patch the rendered Deployment directly."]}),"\n",(0,a.jsxs)(t.p,{children:["There is a complication: the Operator runs a reconcile loop, and patches applied to a live Deployment are overwritten the next time it re-renders. The reliable sequence is therefore: pause the Operator, scale the Deployment to zero, apply every patch in a single command, scale back up, and restore the Operator only after the Pods are Ready. Scaling to zero also sidesteps a rolling-update deadlock: with replicas equal to available GPUs (two replicas, two single-GPU nodes), the default",(0,a.jsx)(t.code,{children:"maxSurge"})," tries to start a new Pod before freeing an old one, and the new Pod sticks in Pending forever waiting for a GPU that never frees."]}),"\n",(0,a.jsx)(t.p,{children:"Start by pausing the Operator and draining the Deployment:"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:'DEPLOY_NAME="qwen2-7b-instruct-kvcache"\n\n# 1. Pause the Operator so its reconcile loop cannot overwrite the patch\nkubectl scale deployment hyperpod-inference-controller-manager \\\n  -n hyperpod-inference-system --replicas=0\n\n# 2. Scale the model Deployment to 0 (frees the GPUs; avoids the maxSurge deadlock)\nkubectl scale deployment $DEPLOY_NAME --replicas=0\n'})}),"\n",(0,a.jsx)(t.p,{children:"Next, find where the Operator placed LMCACHE_REMOTE_URL in the container's env array. Don't hardcode the index, it varies between Operator versions:"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:"# 3. List env vars with their indices; note the index of LMCACHE_REMOTE_URL\nkubectl get deployment $DEPLOY_NAME \\\n  -o jsonpath='{.spec.template.spec.containers[0].env}' | \\\n  python3 -c \"import json,sys; [print(f'{i}: {e[\\\"name\\\"]}') for i,e in enumerate(json.load(sys.stdin))]\"\n"})}),"\n",(0,a.jsxs)(t.p,{children:["Now, apply all three patches in one command, the URL replacement, the Curvine volume, and its mount. Replace",(0,a.jsx)(t.code,{children:"N"})," with the index you found in the previous step:"]}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:'# 4. Apply ALL patches in one shot\nkubectl patch deployment $DEPLOY_NAME --type=\'json\' -p=\'[\n  {"op": "replace", "path": "/spec/template/spec/containers/0/env/N/value",\n   "value": "fs://localhost:0/mnt/curvine/l2cache/"},\n  {"op": "add", "path": "/spec/template/spec/volumes/-", "value":\n   {"name": "curvine-cache", "persistentVolumeClaim": {"claimName": "curvine-pvc"}}},\n  {"op": "add", "path": "/spec/template/spec/containers/0/volumeMounts/-", "value":\n   {"name": "curvine-cache", "mountPath": "/mnt/curvine/l2cache"}}\n]\'\n'})}),"\n",(0,a.jsxs)(t.p,{children:["A note on the URL format:",(0,a.jsx)(t.code,{children:"localhost:0"})," is a placeholder. LMCache's",(0,a.jsx)(t.code,{children:"parse_remote_url"})," requires a non-empty host and port even for the filesystem connector. The",(0,a.jsx)(t.code,{children:"fs://"})," connector ignores them and uses only the path portion (",(0,a.jsx)(t.code,{children:"/mnt/curvine/l2cache/"}),"), which is where the Curvine PVC is mounted."]}),"\n",(0,a.jsx)(t.p,{children:"Verify the patch landed before scaling anything back up. You want exactly one LMCACHE_REMOTE_URL, set to the fs:// value, plus the volume and mount:"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:"# 5. Verify: volume present, exactly ONE LMCACHE_REMOTE_URL with the fs:// value\nkubectl get deployment $DEPLOY_NAME \\\n  -o jsonpath='{.spec.template.spec.volumes[?(@.name==\"curvine-cache\")]}{\"\\n\"}'\n\nkubectl get deployment $DEPLOY_NAME \\\n  -o jsonpath='{.spec.template.spec.containers[0].env}' | \\\n  python3 -m json.tool | grep -A1 LMCACHE_REMOTE_URL\n"})}),"\n",(0,a.jsx)(t.p,{children:"Finally, bring the Pods back and, only after they're ready, restore the Operator. Restoring it earlier triggers an immediate reconcile that re-renders the Deployment and discards the patch:"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:"# 6. Scale back up and wait for 2 Pods at 3/3 Running\nkubectl scale deployment $DEPLOY_NAME --replicas=2\nkubectl get pods -l app=$DEPLOY_NAME -w\n\n# 7. Restore the Operator ONLY after the Pods are Ready\nkubectl scale deployment hyperpod-inference-controller-manager \\\n  -n hyperpod-inference-system --replicas=1\n"})}),"\n",(0,a.jsx)(t.p,{children:"The patch persists as long as the Operator has no reason to re-render the Deployment. Editing the CRD, upgrading the Operator, or deleting the Deployment all trigger a re-render that drops the patch, re-run this section afterwards. For long-running production use, replace the manual patch with a MutatingWebhook or a Kyverno ClusterPolicy that injects the Curvine volume, mount, and URL automatically on every render, so the Operator can reconcile freely."}),"\n",(0,a.jsx)(t.h3,{id:"stage-5-verify-l2-write-hit-and-cross-pod-sharing",children:"Stage 5: Verify L2 write, hit, and cross-Pod sharing"}),"\n",(0,a.jsxs)(t.p,{children:["A short prompt won't trigger an L2 write: LMCache stores a block only once a prompt crosses the 256-token chunk size. The following test uses a real long document (Alice's Adventures in Wonderland from Project Gutenberg) and sends the byte-identical request to two different Pods on two different nodes: the first Pod computes the prefill and writes to Curvine, the second reads that same entry back over the shared FUSE mount. We call each Pod's own",(0,a.jsx)(t.code,{children:"localhost:8000"})," to bypass the router, so we control which replica writes and which reads."]}),"\n",(0,a.jsx)(t.p,{children:"Identify the two Pods and confirm the shared FUSE mount:"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:"DEPLOY_NAME=\"qwen2-7b-instruct-kvcache\"\n\nPODS=($(kubectl get pods -l app=$DEPLOY_NAME --field-selector=status.phase=Running \\\n  -o jsonpath='{.items[*].metadata.name}'))\n\nPOD1=${PODS[0]}; POD2=${PODS[1]}\n\nkubectl exec $POD1 -c $DEPLOY_NAME -- df -h /mnt/curvine/l2cache   # expect a curvine filesystem\n"})}),"\n",(0,a.jsx)(t.p,{children:"Build one deterministic payload (approximately 1,900 tokens) from the first 8 KB of the book, and reuse the SAME file for both requests so the cache keys match:"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:'curl -s -L https://www.gutenberg.org/files/11/11-0.txt -o /tmp/alice.txt\n\npython3 - <<\'PY\' > /tmp/payload.json\nimport json\ntext = " ".join(open("/tmp/alice.txt", encoding="utf-8").read().split())[:8000]\nprint(json.dumps({"model":"/opt/ml/model",\n    "messages":[{"role":"system","content":"Reference text:\\n"+text},\n                {"role":"user","content":"In one sentence, what is this text about?"}],\n    "max_tokens":50, "temperature":0}))\nPY\n'})}),"\n",(0,a.jsx)(t.p,{children:"Send it to POD1 first, which is cold and writes to L2, then to POD2, which reads the same entry across nodes, and inspect the LMCache logs on each:"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:'cat /tmp/payload.json | kubectl exec -i $POD1 -c $DEPLOY_NAME -- \\\n  curl -s http://localhost:8000/v1/chat/completions -H "Content-Type: application/json" -d @-\n\ncat /tmp/payload.json | kubectl exec -i $POD2 -c $DEPLOY_NAME -- \\\n  curl -s http://localhost:8000/v1/chat/completions -H "Content-Type: application/json" -d @-\n\nkubectl logs $POD1 -c $DEPLOY_NAME | grep -E "Stored|hit tokens"\nkubectl logs $POD2 -c $DEPLOY_NAME | grep -E "Retrieved|hit tokens"\n'})}),"\n",(0,a.jsx)(t.p,{children:"Observed results (two replicas on two separate G6e nodes):"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:"# POD1 (node A) -- cold: 0 hits, computes prefill, writes all 1,925 tokens to Curvine\nLMCache INFO: Reqid: ..., Total tokens 1925, LMCache hit tokens: 0, need to load: 0\nLMCache INFO: Stored 1925 out of total 1925 tokens. size: 0.1028 GB, cost 10.71 ms, throughput: 9.60 GB/s\n\n# POD2 (node B) -- reads the SAME entry over Curvine: 100% cross-Pod hit, no prefill\nLMCache INFO: Reqid: ..., Total tokens 1925, LMCache hit tokens: 1925, need to load: 1924\nLMCache INFO: Retrieved 1925 out of 1925 required tokens. cost 55.75 ms, throughput: 1.84 GB/s\n"})}),"\n",(0,a.jsx)(t.p,{children:"The 1,925/1,925 hit on POD2 is a 100 percent cross-Pod cache hit for a request POD2 never prefilled. This is the proof that the shared L2 works. Confirm the same cache files are visible from both Pods (the shared ReadWriteMany mount):"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{children:"kubectl exec $POD1 -c $DEPLOY_NAME -- ls /mnt/curvine/l2cache/\nkubectl exec $POD2 -c $DEPLOY_NAME -- ls /mnt/curvine/l2cache/\n# identical vllm@...bfloat16.data files\n"})}),"\n",(0,a.jsx)(t.p,{children:"Measured on this deployment: cross-Pod hit rate 100 percent (1,925 / 1,925 tokens), same-node L2 write approximately 9.6 GB/s, cross-node L2 read approximately 1.8 GB/s, cross-node load latency approxmiately 56 ms for 1,925 tokens. Without shared L2, the POD2 request would have been a full cold prefill."}),"\n",(0,a.jsx)(t.h2,{id:"benchmarking",children:"Benchmarking"}),"\n",(0,a.jsx)(t.p,{children:"To quantify the benefit of the shared L2 tier, we ran two complementary benchmarks against the architecture described above. Both use Qwen2-7B-Instruct (fp16, tensor parallelism 1), served by two vLLM replicas on two separate GPU nodes, with Curvine workers co-located on those nodes (required anti-affinity) and LMCache's default 256-token chunk size. In both tests we bypass the router and address each Pod directly, so we control which replica writes the cache and which reads it. Request one goes to Pod A: a cold start that does a full prefill, then writes asynchronously to Curvine. The byte-identical request then goes to Pod B on the other node, which has no local cache and must load everything over the shared L2 mount. Generation is capped at five tokens with temperature=0, so measured latency is dominated by prefill, the component L2 caching accelerates. The first benchmark sweeps single-shot prompts from 500\u20133,000 tokens to find where L2 reuse pays off (two ml.g5.4xlarge nodes, A10G 24 GB). The second replays a four-turn conversation with accumulating history, 530\u20132,114 prompt tokens, to model multi-turn dialogue (one ml.g6e.4xlarge and one ml.g6.16xlarge node)."}),"\n",(0,a.jsx)(t.p,{children:"Cross-Pod L2 reuse delivered up to a 2.7\xd7 TTFT improvement, with an optimal range. For prompts of 1,000 tokens and above, Pod B hit 100 percent of tokens written by Pod A and skipped prefill entirely: speedup grew from 1.7\xd7 at 1,000 tokens to 2.7\xd7 at 2,500 tokens, where a cold 774 ms request completed in 287 ms. Below roughly 1,000 tokens the L2 round-trip costs about as much as simply recomputing the prefill (0.99\xd7 at 500 tokens), for short prompts, the GPU and CPU tiers (L0/L1) are the right place to hit, which is exactly what prefix-aware routing encourages. Beyond 3,000 tokens the relative speedup eases back (2.2\xd7) as cross-node read time grows, but the absolute saving keeps rising, 490 ms saved per request at 3,000 tokens, the largest in the sweep. Figure 3 plots cold-prefill TTFT against cross-Pod L2-hit TTFT for each prompt length. The cold bars grow with prompt size while the L2-hit bars stay nearly flat, and the widening gap between them is the time cross-Pod reuse saves."}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"Figure 3: TTFT speedup from cross-Pod L2 reuse",src:n(77203).A+"",width:"1834",height:"911"})}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.em,{children:"Figure 3: TTFT speedup from cross-Pod L2 reuse compared to prompt length (single-shot, Pod A writes / Pod B reads, ml.g5.4xlarge)"})}),"\n",(0,a.jsx)(t.p,{children:"The multi-turn benchmark shows the same effect in a dialogue shape. Four turns of accumulating conversation history were sent to Pod A (writing 2,048 tokens of KV cache, 109 MB to Curvine at 7.8 GB/s aggregate, a 3\u20134 ms detour per turn on the local NVMe path), then replayed against Pod B. Every turn hit 100 percent in L2, cutting total conversation latency from 4.21 s to 3.25 s (1.30\xd7), with per-turn speedup growing as history accumulated, from 1.22\xd7 at 530 tokens to 1.34\xd7 at 2,114 tokens. Speedup is smaller here because these GPUs (L40S/L4) prefill faster, a cache hit saves less when prefill was cheap to begin with. On smaller accelerators, expect the higher end of the range. Figure 4 shows the same comparison across the four dialogue turns, first pass versus replay on the second node, with per-turn speedup labeled above each pair."}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"Figure 4: Multi-turn dialogue",src:n(93596).A+"",width:"1834",height:"901"})}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.em,{children:"Figure 4: Multi-turn dialogue, first pass compared to replay on a second node (Pod A writes / Pod B reads, ml.g6e.4xlarge / ml.g6.16xlarge)"})}),"\n",(0,a.jsx)(t.p,{children:"Two practical takeaways from the numbers. First, writes incur little cost: they land on the node-local NVMe worker at near-disk speed. Reads are the cost to manage, they cross the Pod network, which is why prefix-aware routing matters: every request the router lands on the replica that already holds the cache turns a approximately 60\u2013200 ms L2 read into a sub-millisecond L0 hit. Second, the economics improve with context length up to the network's comfort zone (approximately 2,500 tokens here), and workloads dominated by prompts under approximately 1,000 tokens should rely on L0/L1 rather than L2."}),"\n",(0,a.jsx)(t.p,{children:"As with any benchmark, these figures are environment-specific: speedup depends on the GPU generation (faster prefill narrows the gap), inter-node network bandwidth, and prompt-overlap ratio of the workload. Both tests measure serial single requests to isolate the caching path. Concurrent-load behavior additionally benefits from the router's hit-rate optimization and is workload-dependent."}),"\n",(0,a.jsx)(t.h2,{id:"solution-benefits",children:"Solution benefits"}),"\n",(0,a.jsx)(t.p,{children:"After rollout, measurable benefits are observed across multiple dimensions."}),"\n",(0,a.jsx)(t.h3,{id:"enabling-kv-cache-for-large-models-on-small-instances-nvme-as-a-safety-net",children:"Enabling KV cache for large models on small instances: NVMe as a safety net"}),"\n",(0,a.jsx)(t.p,{children:"Cost-efficient instances such as ml.g6e.4xlarge (48 GB per GPU) suffice to host long-tail models like Qwen2-7B and Llama-3-8B while preserving high KV cache hit rates on long prompts (thousands of tokens). The KV cache is no longer bounded by GPU memory: hottest data resides on the GPU, warm data on host CPU memory, and cold data is offloaded to the pooled node-local NVMe, with L2 capacity scaling linearly to the hundreds of GBs (100 Gi NVMe per Worker \xd7 N nodes). Consequently, multi-tenant long-prompt workloads previously requiring ml.g6e.12xlarge or ml.p5.24xlarge can be downsized onto smaller instances, reducing per-endpoint cost. The actual savings depend on the model and traffic profile."}),"\n",(0,a.jsx)(t.h3,{id:"unified-fuse-mount-for-cross-pod-l2-cache-sharing",children:"Unified FUSE mount for cross-Pod L2 cache sharing"}),"\n",(0,a.jsx)(t.p,{children:"This is the principal differentiator of this solution relative to a plain LMCache + node-local disk setup. When a request routes to a Pod that didn't compute the prefill, both L0 and L1 miss, but the Pod reads the KV cache another replica wrote to the shared L2 mount and skips prefill entirely, so TTFT drops sharply."}),"\n",(0,a.jsx)(t.p,{children:"Figure 5 traces this path: Pod 1 computes a prefill and writes the KV cache to the shared Curvine mount. A later request with the same prefix routes to Pod 2, which misses L0 and L1, reads the cache from Curvine over FUSE, and skips prefill."}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"Figure 5: Cross-Pod L2 cache sharing flow",src:n(23013).A+"",width:"1882",height:"1026"})}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.em,{children:"Figure 5: Cross-Pod L2 cache sharing flow"})}),"\n",(0,a.jsx)(t.p,{children:"The comparative significance is direct: without shared L2, caches in Pod1 and Pod2 are mutually invisible, so routing to Pod2 amounts to a miss and triggers a full prefill. With shared L2, caches written by Pod1 are directly reusable by Pod2, and aggregate hit rate increases as the number of replicas grows. Combined with the Inference Operator's built-in prefixaware / kvaware routing, same-prefix requests are preferentially dispatched to the replica with the highest hit probability, further reducing the frequency of cross-node L2 reads."}),"\n",(0,a.jsx)(t.p,{children:"Latency grows with tier depth: sub-millisecond for GPU (L0) hits, low milliseconds for CPU (L1), and tens of milliseconds for cross-Pod L2, but every tier is far cheaper than re-running the full prefill. See the Benchmarking section for measured figures."}),"\n",(0,a.jsx)(t.h3,{id:"operations-and-cost",children:"Operations and cost"}),"\n",(0,a.jsx)(t.p,{children:"The fully managed nature of SageMaker HyperPod deploys the ai-toolkit DaemonSet automatically to every node, with new nodes self-onboarding and memory-management details requiring no operator attention. With Curvine, you get elastic scaling from Workers that use hostPath + NVMe instance store at zero additional storage cost (NVMe is included with the instance), while Master component uses only a small EBS volume (10\u201350 Gi) for metadata. The Inference Operator owns vLLM Pod lifecycle, intelligent routing, Cert Manager, and metrics, so workload teams maintain only a single CRD."}),"\n",(0,a.jsx)(t.h2,{id:"clean-up",children:"Clean up"}),"\n",(0,a.jsx)(t.p,{children:"To avoid ongoing charges, tear down the test environment in the reverse order of the implementation:"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:["Delete the inference endpoint to stop GPU consumption:",(0,a.jsx)(t.code,{children:"kubectl delete inferenceendpointconfig ${ENDPOINT_NAME} -n ${NAMESPACE}"}),". The Inference Operator removes the rendered Deployment, Service, router config, and ALB target group automatically."]}),"\n",(0,a.jsxs)(t.li,{children:["Uninstall Curvine and its CSI:",(0,a.jsx)(t.code,{children:"helm uninstall curvine -n curvine && helm uninstall curvine-csi -n curvine"}),", then",(0,a.jsx)(t.code,{children:"kubectl delete pvc -n curvine --all"})," and",(0,a.jsx)(t.code,{children:"kubectl delete ns curvine"}),". Confirm the underlying EBS volumes for Curvine Master component are released (the reclaim policy on",(0,a.jsx)(t.code,{children:"ebs-sc"})," determines whether the volume is deleted or retained). The node-local NVMe used as L2 storage is ephemeral and freed automatically."]}),"\n",(0,a.jsxs)(t.li,{children:["If the cluster won't be reused for tiered KV cache testing, remove the Inference Operator add-on (",(0,a.jsx)(t.code,{children:"aws eks delete-addon --addon-name amazon-sagemaker-hyperpod-inference"}),") and disable Tiered Storage on the HyperPod cluster:",(0,a.jsx)(t.code,{children:"aws sagemaker update-cluster --cluster-name hyperpod-cluster-eks --tiered-storage-config Mode=Disable --node-recovery Automatic"}),". The same",(0,a.jsx)(t.code,{children:"--node-recovery"})," flag is required here, as in Stage 1."]}),"\n",(0,a.jsx)(t.li,{children:"Finally, delete any S3 objects (model weights, exported TLS certificates) and Amazon CloudWatch log groups created during testing if they aren't needed for future runs. Scaling the GPU instance group to zero, or deleting the HyperPod cluster entirely if it was created solely for this evaluation, stops the largest cost driver."}),"\n"]}),"\n",(0,a.jsx)(t.h2,{id:"conclusion",children:"Conclusion"}),"\n",(0,a.jsx)(t.p,{children:"Deploying large language models on cost-efficient instances doesn't require sacrificing latency. The tiered KV cache architecture described in this post, which combines vLLM's GPU prefix cache, LMCache's CPU offload layer, and Curvine's distributed NVMe pool, all orchestrated by the HyperPod Inference Operator, demonstrates that you can run a fleet of model replicas on ml.g6e.4xlarge instances while maintaining a 100 percent cross-Pod cache hit rate and cross-node retrieval latency in the tens of milliseconds."}),"\n",(0,a.jsx)(t.p,{children:"This architecture suits workloads with high prompt overlap: RAG pipelines that reuse retrieved context, multi-turn dialogue where session history accumulates, and multi-tenant deployments sharing a system prompt template. If your traffic looks like this and you want lower TTFT on smaller instances, it's worth evaluating. The same L2 tier also underpins prefill/decode-disaggregated (PD) serving in the HyperPod Inference Operator, which routes KV exchange between prefill and decode pools through the same LMCache stack, so Curvine can extend to large multi-node models through the standard LMCACHE_REMOTE_URL override, subject to the cross-node latencies shown in Benchmarking."}),"\n",(0,a.jsx)(t.p,{children:"Get started:"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsx)(t.li,{children:"Learn more about Amazon SageMaker HyperPod on the service detail page."}),"\n",(0,a.jsx)(t.li,{children:"Activate Managed Tiered KV Cache on your HyperPod cluster using the HyperPod model deployment documentation."}),"\n",(0,a.jsx)(t.li,{children:"Review the Managed Tiered KV Cache and Intelligent Routing blog post for detailed benchmarking results and routing strategy guidance."}),"\n",(0,a.jsx)(t.li,{children:"Deploy the Curvine distributed filesystem using the Curvine Helm charts."}),"\n",(0,a.jsx)(t.li,{children:"Explore vLLM and LMCache for details on cache connector configuration and eviction policies."}),"\n",(0,a.jsx)(t.li,{children:"For cluster setup and Inference Operator installation, see the HyperPod setup guide."}),"\n"]}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsxs)(t.em,{children:["This article is reposted from the ",(0,a.jsx)(t.a,{href:"https://aws.amazon.com/cn/blogs/machine-learning/tiered-kv-cache-for-large-llms-on-amazon-sagemaker-hyperpod-with-curvine/",children:"AWS Machine Learning Blog"})," with the original content preserved."]})})]})}function h(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},77203:(e,t,n)=>{n.d(t,{A:()=>r});const r=n.p+"assets/images/figure-3-dc486800bca183dc118b70d933dc5201.png"},87329:(e,t,n)=>{n.d(t,{A:()=>r});const r=n.p+"assets/images/figure-1-85a06de2f029dac0449b88373fe828b3.png"},93596:(e,t,n)=>{n.d(t,{A:()=>r});const r=n.p+"assets/images/figure-4-66240760747fcfb720dc6cba8e5e5e32.png"}}]);